function towerTiles(length) {
  const ways = (n) => (n <= 1 ? 1 : (ways(n - 1) + ways(n - 2)) % 1000000007);
  return ways(length);
}

function towerTiles(length) {
  const MOD = 1000000007;
  let a = 1, b = 1;
  for (let i = 2; i <= length; i++) {
    const next = (a + b) % MOD;
    a = b;
    b = next;
  }
  return b;
}
